// A recovery notice: any alert_key that is currently OPEN (resolved_at IS NULL in wf_alert)
// but is NOT among this sweep's current findings has cleared -- the underlying problem
// stopped reproducing. Mark it resolved and notify once.
const items = $input.all();
const currentKeys = new Set(
  items.filter(i => i.json.source === 'current_finding').map(i => i.json.alert_key)
);
const openAlerts = items.filter(i => i.json.source === 'open_alert');
const resolved = openAlerts.filter(i => !currentKeys.has(i.json.alert_key));
return resolved.map(i => ({ json: i.json }));

// Same placeholder-item quirk as the alert cooldown guard: a 0-row UPDATE still
// emits a {"success": true} item. Only pass through rows that actually got
// resolved_at set this sweep (i.e. genuinely newly-resolved alerts).
return $input.all().filter(item => item.json.alert_key !== undefined && item.json.alert_key !== null);

// Only pass through items where the cooldown guard actually returned an alert_key
// (i.e. an alert was NOT suppressed by the 30-min cooldown window).
// NOTE: n8n's Postgres node always emits one output item per input item, even when
// an UPDATE's WHERE clause matches 0 rows (it returns a {"success": true} placeholder
// instead of dropping the item). Without this filter, Slack would fire for every
// finding on every sweep cycle regardless of cooldown -- this node is what makes the
// 30-minute alert cooldown actually work end-to-end. Verified via T6 in the test matrix.
return $input.all().filter(item => item.json.alert_key !== undefined && item.json.alert_key !== null);
